ts),\n                'CLI raw leaf RUN/PASS or FAIL/SKIP mismatch')\n        proof_path = bounded_path(case_result['proof_ref']['path'])\n        export_root = bounded_path(cli_scope['new_export_root'])\n        expected_proof = (export_root/'.cli43-build'/'case-evidence'/label/\n                          ('TestCLIProtocolInteractiveAuthority_'+case)/'closed-proof.json')\n        require(proof_path == expected_proof, 'CLI proof outside original export/case')\n        reader.verify(case_result['proof_ref'])\n",
